請問下列程式碼片段有何問題？（每小題 10 分，共 20 分）
①static jmp_buf buf_alrm;static void sig_alrm(int signo) {longjmp(buf_alrm, 1);}unsigned int myfunc() {signal(SIGALRM, sig_alrm);alarm(5);if(setjmp(buf_alrm) != 0) {/* handle time out */. . .} . . . }
②int worktogether() {pid_t myid;if ((myid = vfork()) < 0) {fprintf(stderr, "vfork error"); exit() ; }else if (myid == 0) {printf("Child Process: %d.\n", getpid());return(0);}else {waitpid(myid,NULL,0);printf("Parent Process: %d.\n", getpid());}}int main() {worktogether();exit(0);}
